  assert.ok(Math.abs(hold.x - patrol.x) > 20 || Math.abs(hold.lift - patrol.lift) > 16, "not Sash's cup");
  assert.ok(Math.abs(hold.x - holdClip.x) > 20 || Math.abs(hold.lift - holdClip.lift) > 16, "not Fuse's sash clip");
  assert.ok(Math.abs(hold.lift - sill.lift) > 40, "not a generic sill");
  const on0 = P.loopOnPath(0, { x: 40, lift: 0 }, { x: hold.x, lift: hold.lift });
  const on1 = P.loopOnPath(1, { x: 40, lift: 0 }, { x: hold.x, lift: hold.lift });
