  assert.ok(tip1.rot < 20, "a lean, not a fall");
  const hold = P.leanHoldPath(0.5);
  assert.ok(Math.abs(hold.rot - tip1.rot) < 0.2, "she remains leaned");
  const off0 = P.leanOffPath(0, { x: page.x, lift: page.lift }, { x: page.x + 60, lift: 0 });
  const off1 = P.leanOffPath(1, { x: page.x, lift: page.lift }, { x: page.x + 60, lift: 0 });
  assert.ok(Math.abs(off0.x - page.x) < 2);
  assert.ok(Math.abs(off1.lift) < 2);
  let play = P.beginPlay(target, target.approachX);
  const seen = new Set();
