  const onMid = P.droneOnPath(0.36, { x: 40, lift: 0 }, { x: air.x, lift: air.lift });
  const on1 = P.droneOnPath(1, { x: 40, lift: 0 }, { x: air.x, lift: air.lift });
  assert.ok(Math.abs(on0.lift) < 2);
  assert.ok(Math.abs(on1.lift - air.lift) < 6);
  assert.ok(onMid.lift > on0.lift, "he lifts into the sky");
  const still = P.dronePath(0);
  const hang = P.dronePath(0.1);
  const pulse = P.dronePath(0.45);
  const after = P.dronePath(1);
  assert.ok(Math.abs(still.rot) < 1, "not yet");
  assert.ok(hang.lift > 0, "a hang in the sky, not a scrape");
  assert.ok(pulse.lift > 6, "one drone into the sky");
  assert.ok(Math.abs(pulse.x) < 2, "a drone, not spoil and not a circle");
  assert.ok(after.lift > 0, "he finishes still hanging");
