  const target = P.pickTarget([WIN], 80, "mussel", WORK, P.SPRITE);
  assert.ok(target);
  assert.equal(target.kind, "filter");
  assert.equal(target.side, "bed");
  assert.equal(target.leave, "silt");
  assert.notEqual(target.kind, "hinge");
  assert.notEqual(target.kind, "sill");
  assert.notEqual(target.kind, "rasp");
  assert.notEqual(target.kind, "claw");
  assert.notEqual(target.kind, "ring");
  assert.notEqual(target.kind, "cover");
  assert.notEqual(target.kind, "trail");
  assert.notEqual(target.kind, "puff");
  assert.notEqual(target.kind, "plop");
  assert.notEqual(target.kind, "knob");
  assert.notEqual(target.kind, "lid");
  assert.notEqual(target.kind, "gape");
  assert.notEqual(target.kind, "circle");
  assert.ok(target.holdLift > 36, "she sits the meeting-rail gap, not the floor");
  assert.ok(P.DUR.filter < P.DUR.filterHold, "the filter is the tell; the hold is the clamp after");
  assert.ok(P.DUR.filterOn !== P.DUR.raspOn);
  assert.ok(P.DUR.filterOn !== P.DUR.clawOn);
  assert.ok(P.DUR.filterOn !== P.DUR.ringOn);
  assert.ok(P.DUR.filterOn !== P.DUR.coverOn);
  assert.ok(P.DUR.filterOn !== P.DUR.trailOn);
  assert.ok(P.DUR.filterOn !== P.DUR.puffOn);
  assert.ok(P.DUR.filterOn !== P.DUR.plopOn);
  assert.ok(P.DUR.filterOn !== P.DUR.knobOn);
  assert.ok(P.DUR.filterOn !== P.DUR.lidOn);
  assert.ok(P.DUR.filterOn !== P.DUR.gapeOn);
  assert.ok(P.DUR.filterOn !== P.DUR.sillHop);
  assert.ok(P.DUR.filter !== P.DUR.rasp);
  assert.ok(P.DUR.filter !== P.DUR.claw);
  assert.ok(P.DUR.filter !== P.DUR.ring);
  assert.ok(P.DUR.filter !== P.DUR.cover);
  assert.ok(P.DUR.filter !== P.DUR.trail);
  assert.ok(P.DUR.filter !== P.DUR.puff);
  assert.ok(P.DUR.filter !== P.DUR.plop);
  assert.ok(P.DUR.filter !== P.DUR.knob);
  assert.ok(P.DUR.filter !== P.DUR.lid);
  assert.ok(P.DUR.filter !== P.DUR.circle);
  assert.ok(P.DUR.filterHold !== P.DUR.raspHold);
  assert.ok(P.DUR.filterHold !== P.DUR.clawHold);
  assert.ok(P.DUR.filterHold !== P.DUR.ringHold);
  assert.ok(P.DUR.filterHold !== P.DUR.coverHold);
  assert.ok(P.DUR.filterHold !== P.DUR.trailHold);
  assert.ok(P.DUR.filterHold !== P.DUR.puffHold);
  assert.ok(P.DUR.filterHold !== P.DUR.plopHold);
  assert.ok(P.DUR.filterHold !== P.DUR.drawHold);
  assert.ok(P.DUR.filterHold !== P.DUR.fillHold);
  assert.ok(P.DUR.filterOff !== P.DUR.raspOff);
  assert.ok(P.DUR.filterOff !== P.DUR.clawOff);
  assert.ok(P.DUR.filterOff !== P.DUR.sillDown);
  const bed = P.filterPoint(WIN, P.SPRITE, WORK);
  const rim = P.raspPoint(WIN, P.SPRITE, WORK);
  const wash = P.clawPoint(WIN, P.SPRITE, WORK);
  const throat = P.ringPoint(WIN, P.SPRITE, WORK);
  const well = P.coverPoint(WIN, P.SPRITE, WORK);
  const horn = P.trailPoint(WIN, P.SPRITE, WORK);
  const leaf = P.puffPoint(WIN, P.SPRITE, WORK);
  const weep = P.plopPoint(WIN, P.SPRITE, WORK);
  const lift = P.knobPoint(WIN, P.SPRITE, WORK);
  const latch = P.lidPoint(WIN, P.SPRITE, WORK);
  const rail = P.dustPoint(WIN, P.SPRITE, WORK);
  assert.ok(Math.abs(bed.x - rim.x) > 20 || Math.abs(bed.lift - rim.lift) > 12, "not Whorl");
  assert.ok(Math.abs(bed.x - wash.x) > 20 || Math.abs(bed.lift - wash.lift) > 12, "not Pinch");
  assert.ok(Math.abs(bed.x - throat.x) > 20 || Math.abs(bed.lift - throat.lift) > 12, "not Slip");
  assert.ok(Math.abs(bed.x - well.x) > 20 || Math.abs(bed.lift - well.lift) > 12, "not Dapple");
  assert.ok(Math.abs(bed.x - horn.x) > 20 || Math.abs(bed.lift - horn.lift) > 12, "not Eft");
