  assert.ok(P.DUR.foldOn > P.DUR.fold, "a fly up, not the fold");
  assert.ok(P.DUR.foldOn !== P.DUR.hourOn);
  assert.ok(P.DUR.foldOn !== P.DUR.hang);
  assert.ok(P.DUR.foldOn !== P.DUR.croakOn);
  assert.ok(P.DUR.foldOn !== P.DUR.perchOn);
