  assert.equal(P.playFor("bumblebee"), "forage");
  assert.equal(P.playFor("leafcutter"), "snip");
  assert.equal(P.playFor("leech"), "drink");
  assert.equal(P.playFor("gibbon"), "sing");
  assert.equal(P.playFor("sloth"), "reach");
  assert.equal(P.playFor("widow"), "hang");
  assert.equal(P.playFor("parrot"), "hook");
  assert.equal(P.playFor("sundew"), "curl");
  assert.equal(P.playFor("colugo"), "cling");
  assert.notEqual(P.playFor("kinkajou"), "sip");
  assert.notEqual(P.playFor("kinkajou"), "wrist");
  assert.notEqual(P.playFor("kinkajou"), "drink");
  assert.notEqual(P.playFor("kinkajou"), "hang");
  assert.notEqual(P.playFor("kinkajou"), "hook");
  assert.notEqual(P.playFor("kinkajou"), "curl");
