  assert.equal(target.leave, "unhook");
  assert.notEqual(target.kind, "sip");
  assert.notEqual(target.kind, "wrist");
  assert.notEqual(target.kind, "forage");
  assert.notEqual(target.kind, "snip");
  assert.notEqual(target.kind, "drink");
  assert.notEqual(target.kind, "sing");
  assert.notEqual(target.kind, "sill");
  assert.ok(target.holdLift > 10, "she wraps a window-box bloom as a nectar cup, not the floor");
  assert.ok(P.DUR.wrapHold > P.DUR.wrap, "the wrap is the tell; the hold is the unhook wait");
