  assert.ok(P.DUR.wrapOn !== P.DUR.sipOn);
  assert.ok(P.DUR.wrapOn !== P.DUR.forageOn);
  assert.ok(P.DUR.wrapOn !== P.DUR.snipOn);
  assert.ok(P.DUR.wrapOn !== P.DUR.drinkOn);
  assert.ok(P.DUR.wrapOn !== P.DUR.singOn);
  assert.ok(P.DUR.wrapOn !== P.DUR.reachOn);
  assert.ok(P.DUR.wrapOn !== P.DUR.hang);
  assert.ok(P.DUR.wrapOn !== P.DUR.hookOn);
  assert.ok(P.DUR.wrapOn !== P.DUR.curlOn);
  assert.ok(P.DUR.wrapOn !== P.DUR.sillHop);
  assert.ok(P.DUR.wrap !== P.DUR.sip);
  assert.ok(P.DUR.wrap !== P.DUR.forage);
  assert.ok(P.DUR.wrap !== P.DUR.snip);
  assert.ok(P.DUR.wrap !== P.DUR.drink);
  assert.ok(P.DUR.wrap !== P.DUR.sing);
  assert.ok(P.DUR.wrapHold !== P.DUR.sipHold);
  assert.ok(P.DUR.wrapHold !== P.DUR.singHold);
  assert.ok(P.DUR.wrapOff !== P.DUR.sipOff);
  assert.ok(P.DUR.wrapOff !== P.DUR.singOff);
  assert.ok(P.DUR.wrapOff !== P.DUR.sillDown);
  const cup = P.wrapPoint(WIN, P.SPRITE, WORK);
  const nectar = P.sipPoint(WIN, P.SPRITE, WORK);
  const meadow = P.foragePoint(WIN, P.SPRITE, WORK);
  const foliage = P.snipPoint(WIN, P.SPRITE, WORK);
  const drip = P.drinkPoint(WIN, P.SPRITE, WORK);
  const arm = P.singPoint(WIN, P.SPRITE, WORK);
  const bough = P.reachPoint(WIN, P.SPRITE, WORK);
  const bill = P.hookPoint(WIN, "left", 1, P.SPRITE, WORK);
  assert.ok(cup.lift > 10, "the window-box bloom as a nectar cup, not the floor");
  assert.ok(Math.abs(cup.x - nectar.x) < 2, "same bloom Sip sips");
  assert.ok(cup.lift < nectar.lift - 8, "a wrap on the bloom, not Sip's hover sip");
  assert.ok(Math.abs(cup.x - meadow.x) > 20 || Math.abs(cup.lift - meadow.lift) > 8, "not Thrum's window-box forage");
  assert.ok(Math.abs(cup.x - foliage.x) > 20 || Math.abs(cup.lift - foliage.lift) > 8, "not Disc's window-box leaf snip");
  assert.ok(Math.abs(cup.x - drip.x) > 20 || Math.abs(cup.lift - drip.lift) > 8, "not Latch's sash-drip drink");
  assert.ok(Math.abs(cup.x - arm.x) > 8 || Math.abs(cup.lift - arm.lift) > 20, "not Swing's lamp-side sing");
  assert.ok(Math.abs(cup.x - bough.x) > 8 || Math.abs(cup.lift - bough.lift) > 20, "not Hang's soffit reach");
  assert.ok(Math.abs(cup.x - bill.x) > 8 || Math.abs(cup.lift - bill.lift) > 8, "not Quill's jamb hook");
  const tiny = P.pickTarget([{ id: "tiny", x: 200, y: 80, width: 120, height: 50 }], 80, "kinkajou", WORK, P.SPRITE);
  assert.equal(tiny, null, "a real window-box bloom, not a thin strip");
