test("Sail clings a window jamb as a trunk sail: cling to the jamb, open the skin once, then leave", () => {
  const WIN_B = { id: "hw2", x: 980, y: 90, width: 300, height: 360 };
  assert.equal(P.playFor("colugo"), "cling");
  assert.equal(P.playFor("red_panda"), "cling-dive");
  assert.equal(P.playFor("bat"), "fold");
  assert.equal(P.playFor("porcupine"), "bristle");
  assert.equal(P.playFor("orchid"), "mount");
  assert.equal(P.playFor("sloth"), "reach");
  assert.equal(P.playFor("widow"), "hang");
  assert.equal(P.playFor("dragon"), "drape");
  assert.equal(P.playFor("kinkajou"), "wrap");
  assert.equal(P.playFor("lemur"), "warm");
  assert.equal(P.playFor("flying_squirrel"), "plane");
  assert.notEqual(P.playFor("colugo"), "sail");
  assert.notEqual(P.playFor("colugo"), "fold");
  assert.notEqual(P.playFor("colugo"), "glide");
  assert.notEqual(P.playFor("colugo"), "drape");
  assert.notEqual(P.playFor("colugo"), "mount");
  assert.notEqual(P.playFor("colugo"), "hang");
  assert.notEqual(P.playFor("colugo"), "bristle");
  assert.notEqual(P.playFor("colugo"), "wrap");
  assert.notEqual(P.playFor("colugo"), "sill");
  assert.equal(P.DUR.cling, 0.55, "Rui cling-dive duration stays");
  assert.equal(P.DUR.wrapOn, 1.47, "Wrist wrap durations stay");
  assert.equal(P.DUR.foldOn !== undefined, true);
  const target = P.pickTarget([WIN], 80, "colugo", WORK, P.SPRITE);
  assert.ok(target);
  assert.equal(target.kind, "cling");
  assert.equal(target.side, "trunksail");
  assert.equal(target.leave, "skin");
  assert.notEqual(target.kind, "sail");
  assert.notEqual(target.kind, "fold");
  assert.notEqual(target.kind, "glide");
  assert.notEqual(target.kind, "mount");
  assert.notEqual(target.kind, "bristle");
  assert.notEqual(target.kind, "drape");
  assert.notEqual(target.kind, "sill");
  assert.ok(target.holdLift > 40, "she clings a window jamb as a trunk sail, not the floor");
  assert.ok(P.DUR.skinHold > P.DUR.skin, "the skin sail is the tell; the hold is the leave wait");
  assert.ok(P.DUR.skinOn > 1.2, "a cling to the jamb, not a dart");
  assert.ok(P.DUR.skinOn !== P.DUR.wrapOn);
  assert.ok(P.DUR.skinOn !== P.DUR.bristleOn);
  assert.ok(P.DUR.skinOn !== P.DUR.mountOn);
  assert.ok(P.DUR.skinOn !== P.DUR.foldOn);
  assert.ok(P.DUR.skinOn !== P.DUR.reachOn);
  assert.ok(P.DUR.skinOn !== P.DUR.drapeOn);
  assert.ok(P.DUR.skinOn !== P.DUR.hang);
  assert.ok(P.DUR.skinOn !== P.DUR.sillHop);
  assert.ok(P.DUR.skin !== P.DUR.cling);
  assert.ok(P.DUR.skin !== P.DUR.wrap);
  assert.ok(P.DUR.skin !== P.DUR.bristle);
  assert.ok(P.DUR.skin !== P.DUR.fold);
  assert.ok(P.DUR.skinHold !== P.DUR.wrapHold);
  assert.ok(P.DUR.skinHold !== P.DUR.bristleHold);
  assert.ok(P.DUR.skinOff !== P.DUR.wrapOff);
  assert.ok(P.DUR.skinOff !== P.DUR.sillDown);
  const trunk = P.clingPoint(WIN, P.SPRITE, WORK);
  const pine = P.bristlePoint(WIN, P.SPRITE, WORK);
  const bark = P.mountPoint(WIN, P.SPRITE, WORK);
  const fold = P.foldPoint(WIN, P.SPRITE, WORK);
  const bough = P.reachPoint(WIN, P.SPRITE, WORK);
  const wyrm = P.drapePoint(WIN, "left", P.SPRITE, WORK);
  const cup = P.wrapPoint(WIN, P.SPRITE, WORK);
  const bill = P.hookPoint(WIN, "left", 1, P.SPRITE, WORK);
  assert.ok(trunk.lift > 40, "the interior jamb as a trunk sail, not the floor");
  assert.ok(Math.abs(trunk.x - pine.x) > 4 || Math.abs(trunk.lift - pine.lift) > 8, "same jamb family, not Spine's bristle");
  assert.ok(Math.abs(trunk.x - bark.x) > 8 || Math.abs(trunk.lift - bark.lift) > 8, "same jamb family, not Moth's mount");
  assert.ok(Math.abs(trunk.x - fold.x) > 8 || Math.abs(trunk.lift - fold.lift) > 20, "not Cape's soffit fold");
  assert.ok(Math.abs(trunk.x - bough.x) > 8 || Math.abs(trunk.lift - bough.lift) > 20, "not Hang's soffit reach");
  assert.ok(Math.abs(trunk.x - wyrm.x) > 8 || Math.abs(trunk.lift - wyrm.lift) > 8, "not Vesper's lintel drape");
  assert.ok(Math.abs(trunk.x - cup.x) > 8 || Math.abs(trunk.lift - cup.lift) > 8, "not Wrist's bloom wrap");
  assert.ok(Math.abs(trunk.x - bill.x) > 8 || Math.abs(trunk.lift - bill.lift) > 8, "not Quill's jamb hook");
  const tiny = P.pickTarget([{ id: "tiny", x: 200, y: 80, width: 120, height: 50 }], 80, "colugo", WORK, P.SPRITE);
  assert.equal(tiny, null, "a real window jamb, not a thin strip");
  const short = P.pickTarget([{ id: "short", x: 200, y: 80, width: 180, height: 80 }], 80, "colugo", WORK, P.SPRITE);
  assert.equal(short, null, "a real window jamb needs a trunk");
  const jamb = P.pickTarget([{ id: "jamb", x: 200, y: 80, width: 182, height: 216 }], 80, "colugo", WORK, P.SPRITE);
  assert.ok(jamb, "a real window jamb as a trunk sail");
  const mothJamb = P.pickTarget([{ id: "jamb", x: 200, y: 80, width: 182, height: 216 }], 80, "orchid", WORK, P.SPRITE);
  assert.ok(mothJamb, "Moth still takes the jamb");
  const spineJamb = P.pickTarget([{ id: "jamb", x: 200, y: 80, width: 182, height: 216 }], 80, "porcupine", WORK, P.SPRITE);
  assert.ok(spineJamb, "Spine still takes the jamb");
  const walkOn = P.clingOnPath(0.25, { x: 40, lift: 0 }, { x: trunk.x, lift: trunk.lift });
  const bristleOn = P.bristleOnPath(0.25, { x: 40, lift: 0 }, { x: trunk.x, lift: trunk.lift });
  const mountOn = P.mountOnPath(0.25, { x: 40, lift: 0 }, { x: trunk.x, lift: trunk.lift });
  const foldOn = P.foldOnPath(0.25, { x: 40, lift: 0 }, { x: trunk.x, lift: trunk.lift });
  assert.ok(walkOn.lift > 0, "she clings onto the jamb");
  assert.ok(walkOn.lift < trunk.lift, "a cling on, not already sailing");
  assert.ok(walkOn.lift !== bristleOn.lift, "a cling, not Spine's bristle walk");
  assert.ok(walkOn.lift !== mountOn.lift, "a cling, not Moth's mount");
  assert.ok(walkOn.lift !== foldOn.lift, "a cling, not Cape's fold");
  const open = P.clingPath(0.5);
  const quills = P.bristlePath(0.5);
  const bloom = P.mountPath(0.5);
  const hands = P.foldPath(0.5);
  const coil = P.wrapPath(0.5);
  assert.ok(open.x > 2, "the skin opens");
  assert.ok(open.rot < 20, "a patagium, not a wing");
  assert.ok(open.rot !== quills.rot, "not Spine's bristle");
  assert.ok(open.rot !== bloom.rot, "not Moth's bloom");
  assert.ok(open.rot !== hands.rot, "not Cape's fold");
  assert.ok(open.rot !== coil.rot, "not Wrist's wrap");
  const hold = P.clingHoldPath(0.5);
  assert.ok(Math.abs(hold.rot - 16) < 0.2, "she holds the open skin");
  assert.ok(Math.abs(hold.x - 10.0) < 0.2, "she holds the trunk sail");
  assert.ok(hold.lift > 3, "sailed on the jamb, not a floor sit");
  const off0 = P.clingOffPath(0, { x: trunk.x, lift: trunk.lift, rot: 16 }, { x: trunk.x + 57, lift: 0 });
  const offMid = P.clingOffPath(0.5, { x: trunk.x, lift: trunk.lift, rot: 16 }, { x: trunk.x + 57, lift: 0 });
  const off1 = P.clingOffPath(1, { x: trunk.x, lift: trunk.lift, rot: 16 }, { x: trunk.x + 57, lift: 0 });
  const midEase = 0.5 * 0.5 * (3 - 2 * 0.5);
  assert.ok(Math.abs(off0.x - trunk.x) < 2);
  assert.ok(Math.abs(offMid.x - (trunk.x + 57 * midEase)) < 12, "she leaves, not a drop");
  assert.ok(Math.abs(off1.lift) < 3);
  let play = P.beginPlay(target, target.approachX);
  const seen = new Set();
  const windowIds = new Set();
  for (let i = 0; i < 2400 && play.phase !== "done"; i++) {
    seen.add(play.phase);
    if (play.target && play.target.id) windowIds.add(play.target.id);
    play = P.stepPlay(play, 0.05, { x: play.x, lift: play.lift }, [WIN, WIN_B], WORK, P.SPRITE, { cmd: "idle" });
    assert.notEqual(play.phase, "fold");
    assert.notEqual(play.phase, "bristle");
    assert.notEqual(play.phase, "mount");
    assert.notEqual(play.phase, "wrap");
    assert.notEqual(play.phase, "reach");
    assert.notEqual(play.phase, "drape");
    assert.notEqual(play.phase, "sill-walk");
    if (play.phase === "skin") {
      assert.equal(play.anim, "play");
    }
    if (play.phase === "cling-on") {
      assert.equal(play.anim, "walk");
    }
    if (play.phase === "cling-hold" && play.t > 0) {
      assert.equal(play.anim, "sit");
      assert.ok(Math.abs(play.lift - (play.target.holdLift + 3.8)) < 3, "she holds the open skin on the jamb");
    }
    if (play.phase === "cling-off") {
      assert.equal(play.anim, "walk");
    }
  }
  assert.ok(seen.has("cling-on"));
  assert.ok(seen.has("skin"));
  assert.ok(seen.has("cling-hold"));
  assert.ok(seen.has("cling-off"));
  assert.ok(!seen.has("fold"), "Sail never uses Cape's fold");
  assert.ok(!seen.has("bristle"), "Sail never uses Spine's bristle");
  assert.ok(!seen.has("mount"), "Sail never uses Moth's mount");
  assert.ok(!seen.has("wrap"), "Sail never uses Wrist's wrap");
  assert.ok(!seen.has("glide"), "Sail never starts Glide");
  assert.equal(windowIds.size, 1, "one window");
  assert.equal(play.phase, "done");
  assert.equal(play.lift, 0);
});

test("a moved window refits Sail's trunk-sail jamb; sleep, card, and hide abort; Sail never starts asleep", () => {
  assert.equal(P.canStart({ asleep: true, cmd: "idle" }), false);
  assert.equal(P.canStart({ card: true, cmd: "idle" }), false);
  assert.equal(P.canStart({ hidden: true, cmd: "wander" }), false);
  assert.equal(P.shouldAbort({ cmd: "sleep" }), true);
  assert.equal(P.shouldAbort({ cmd: "hide" }), true);
  assert.equal(P.shouldAbort({ card: true, cmd: "idle" }), true);
  const target = P.pickTarget([WIN], 200, "colugo", WORK, P.SPRITE);
  let play = P.beginPlay(target, target.approachX);
  for (let i = 0; i < 900 && play.phase !== "skin"; i++) {
    play = P.stepPlay(play, 0.05, { x: play.x, lift: play.lift }, [WIN], WORK, P.SPRITE, { cmd: "idle" });
  }
  assert.equal(play.phase, "skin");
  const beforeX = play.target.holdX;
  const moved = { ...WIN, x: WIN.x + 140 };
  play = P.stepPlay(play, 0.05, { x: play.x, lift: play.lift }, [moved], WORK, P.SPRITE, { cmd: "idle" });
  assert.equal(play.phase, "skin");
  assert.ok(Math.abs(play.target.holdX - beforeX) > 40);
  play = P.stepPlay(play, 0.05, { x: play.x, lift: play.lift }, [moved], WORK, P.SPRITE, { asleep: true, cmd: "sleep" });
  assert.ok(play.phase === "drop" || play.phase === "done" || play.phase === "cling-off");
  assert.equal(play.abort, true);
});

