  assert.ok(P.DUR.howlOn !== P.DUR.singOn);
  assert.ok(P.DUR.howlOn !== P.DUR.perchOn);
  assert.ok(P.DUR.howlOn !== P.DUR.cawOn);
  assert.ok(P.DUR.howlOn !== P.DUR.foldOn);
  assert.ok(P.DUR.howlOn !== P.DUR.reachOn);
  assert.ok(P.DUR.howlOn !== P.DUR.stillOn);
  assert.ok(P.DUR.howlOn !== P.DUR.planeOn);
  assert.ok(P.DUR.howlOn !== P.DUR.sillHop);
  assert.ok(P.DUR.howl !== P.DUR.croak);
  assert.ok(P.DUR.howl !== P.DUR.honk);
  assert.ok(P.DUR.howl !== P.DUR.sing);
  assert.ok(P.DUR.howl !== P.DUR.caw);
  assert.ok(P.DUR.howl !== P.DUR.perchTalk);
  assert.ok(P.DUR.howlHold !== P.DUR.croakHold);
  assert.ok(P.DUR.howlHold !== P.DUR.honkHold);
  assert.ok(P.DUR.howlHold !== P.DUR.singHold);
  assert.ok(P.DUR.howlOff !== P.DUR.croakOff);
  assert.ok(P.DUR.howlOff !== P.DUR.honkOff);
  assert.ok(P.DUR.howlOff !== P.DUR.singOff);
  assert.ok(P.DUR.howlOff !== P.DUR.sillDown);
  const crown = P.howlPoint(WIN, P.SPRITE, WORK);
  const rafter = P.croakPoint(WIN, P.SPRITE, WORK);
  const cape = P.foldPoint(WIN, P.SPRITE, WORK);
  const bough = P.reachPoint(WIN, P.SPRITE, WORK);
  const hem = P.stillPoint(WIN, P.SPRITE, WORK);
  const shade = P.perchPoint(WIN, "left", P.SPRITE, WORK);
  const pot = P.cawPoint(WIN, P.SPRITE, WORK);
  const grass = P.honkPoint(WIN, P.SPRITE, WORK);
