  assert.ok(Math.abs(crown.x - rafter.x) > 20, "same transom, not Wedge's croak spot");
  assert.ok(Math.abs(crown.x - cape.x) > 8 || Math.abs(crown.lift - cape.lift) > 20, "not Cape's soffit fold");
  assert.ok(Math.abs(crown.x - bough.x) > 8 || Math.abs(crown.lift - bough.lift) > 20, "not Hang's soffit reach");
  assert.ok(Math.abs(crown.x - hem.x) > 8 || Math.abs(crown.lift - hem.lift) > 20, "not Grin's soffit still");
  assert.ok(Math.abs(crown.x - shade.x) > 8 || Math.abs(crown.lift - shade.lift) > 20, "not Echo's lamp-shade perch");
  assert.ok(Math.abs(crown.x - pot.x) > 8 || Math.abs(crown.lift - pot.lift) > 20, "not Soot's drip-cap caw");
  assert.ok(Math.abs(crown.x - grass.x) > 8 || Math.abs(crown.lift - grass.lift) > 20, "not Vee's apron honk");
  assert.ok(Math.abs(crown.x - arm.x) > 8 || Math.abs(crown.lift - arm.lift) > 20, "not Swing's lamp-side sing");
