  assert.ok(dish.lift > 8, "the window stool as a bark dish, not the floor");
  assert.ok(Math.abs(dish.lift - log.lift) < 2, "the same window stool Link oils; the pose is a roll");
  assert.ok(Math.abs(dish.lift - oak.lift) < 2, "the same window stool Cache buries; the pose is a roll");
  assert.ok(Math.abs(dish.lift - gum.lift) < 2, "the same window stool Gum chews; the pose is a roll");
  assert.ok(Math.abs(dish.lift - bank.lift) < 2, "the same window stool Levee banks; the pose is a roll");
  assert.ok(Math.abs(dish.lift - tray.lift) < 8, "the same window stool family Barb raises; the pose is a roll");
  assert.ok(Math.abs(dish.x - log.x) > 8, "not Link's window-stool oil");
  assert.ok(Math.abs(dish.x - oak.x) > 8, "not Cache's window-stool bury");
  assert.ok(Math.abs(dish.x - gum.x) > 8, "not Gum's window-stool chew");
  assert.ok(Math.abs(dish.x - bank.x) > 8, "not Levee's window-stool bank");
  assert.ok(Math.abs(dish.x - tray.x) > 8, "not Barb's window-stool raise");
  assert.ok(Math.abs(dish.x - crack.x) > 8 || Math.abs(dish.lift - crack.lift) > 8, "not Haste's sash-jamb hunt");
